module fsm (
    input IN,
    input CLK,
    input RST,
    output MATCH
);
// Define parameters for the states
parameter s0 = 3'b000; 
parameter s1 = 3'b001;
parameter s2 = 3'b010;
parameter s3 = 3'b011;
parameter s4 = 3'b100;
parameter s5 = 3'b101;
// Define internal signals
reg [2:0] CURRENT_STATE, NEXT_STATE;
reg MATCH_REG;
// Combinational logic for next state and output
always @(*) begin
    if(RST) begin
        MATCH_REG = 0;
        NEXT_STATE = s0;
    end else begin
        case(CURRENT_STATE)
            s0: begin
                if(IN==1) begin
                    NEXT_STATE = s1;
                    MATCH_REG = 0;
                end else begin
                    NEXT_STATE = s0;
                    MATCH_REG = 0;
                end
            end

            s1: begin
                if(IN==1) begin
                    NEXT_STATE = s1;
                    MATCH_REG = 0;
                end else begin
                    NEXT_STATE = s2;
                    MATCH_REG = 0;
                end
            end

            s2: begin
                if(IN==1) begin
                    NEXT_STATE = s1;
                    MATCH_REG = 0;
                end else begin
                    NEXT_STATE = s3;
                    MATCH_REG = 0;
                end
            end

            s3: begin
                if(IN==1) begin
                    NEXT_STATE = s4;
                    MATCH_REG = 0;
                end else begin
                    NEXT_STATE = s0;
                    MATCH_REG = 0;
                end
            end

            s4: begin
                if(IN==1) begin
                    NEXT_STATE = s5;
                    MATCH_REG = 1;
                end else begin
                    NEXT_STATE = s2;
                    MATCH_REG = 0;
                end
            end

            s5: begin
                if(IN==1) begin
                    NEXT_STATE = s1;
                    MATCH_REG = 0;
                end else begin
                    NEXT_STATE = s2;
                    MATCH_REG = 0;
                end
            end
        endcase
    end
end
// Sequential logic for state register
always @(posedge CLK or posedge RST) begin
    if(RST) begin
        CURRENT_STATE <= s0;
    end else begin
        CURRENT_STATE <= NEXT_STATE;
    end
end
// Assign output MATCH to MATCH_REG
assign MATCH = MATCH_REG;
endmodule
